package com.kFjQzLm.fog;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;

/**
 * AES-128-ECB StringFog implementation (runtime half, in APK).
 *
 * The build-time half lives in android/libs/fog-aes.jar on the buildscript
 * classpath so the StringFog plugin casts it to IStringFog. This runtime copy
 * does not need to implement IStringFog — the generated bytecode calls the
 * concrete class directly by name.
 *
 * Keep method signatures in sync with android/libs/fog-aes.jar.
 */
public class StringFogAesImpl {

    public boolean shouldFog(String str) { return true; }

    public byte[] encrypt(String str, byte[] key) {
        try {
            Cipher c = Cipher.getInstance("AES/ECB/PKCS5Padding");
            c.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(normalizeKey(key), "AES"));
            return c.doFinal(str.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            throw new RuntimeException("AES encrypt", e);
        }
    }

    public String decrypt(byte[] data, byte[] key) {
        try {
            Cipher c = Cipher.getInstance("AES/ECB/PKCS5Padding");
            c.init(Cipher.DECRYPT_MODE, new SecretKeySpec(normalizeKey(key), "AES"));
            return new String(c.doFinal(data), StandardCharsets.UTF_8);
        } catch (Exception e) {
            return "";
        }
    }

    private byte[] normalizeKey(byte[] key) {
        byte[] k = new byte[16];
        for (int i = 0; i < 16; i++) {
            k[i] = key[i % key.length];
        }
        return k;
    }
    
}

